def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    token_pattern = re.compile(
        r"\d+|[A-Z]+[0-9]*|<>|<=|>=|[()+\-*/,:=<>]"
    )
    functions = {"SUM", "MIN", "MAX", "IF"}
    precedence = {
        "=": 0, "<>": 0, "<": 0, "<=": 0, ">": 0, ">=": 0,
        "+": 1, "-": 1,
        "*": 2, "/": 2,
        "neg": 3,
        ":": 4,
    }

    def parse(formula):
        nodes = []
        operators = []
        argument_counts = []
        expect_operand = True

        def reduce_operator():
            op = operators.pop()
            if op == "neg":
                nodes.append(("neg", nodes.pop()))
            else:
                right = nodes.pop()
                left = nodes.pop()
                nodes.append((op, left, right))

        for token in token_pattern.findall(formula):
            if token[0].isdigit():
                nodes.append(("number", int(token)))
                expect_operand = False
            elif token in functions:
                operators.append(token)
                expect_operand = True
            elif token[0].isalpha():
                nodes.append(("ref", token))
                expect_operand = False
            elif token == "(":
                operators.append(token)
                argument_counts.append(1)
                expect_operand = True
            elif token == ",":
                while operators[-1] != "(":
                    reduce_operator()
                argument_counts[-1] += 1
                expect_operand = True
            elif token == ")":
                while operators[-1] != "(":
                    reduce_operator()
                operators.pop()
                count = argument_counts.pop()
                if operators and operators[-1] in functions:
                    function = operators.pop()
                    arguments = tuple(nodes[-count:])
                    del nodes[-count:]
                    nodes.append((function, arguments))
                expect_operand = False
            else:
                op = "neg" if token == "-" and expect_operand else token
                while operators and operators[-1] in precedence:
                    top = operators[-1]
                    if precedence[top] < precedence[op]:
                        break
                    if precedence[top] == precedence[op] and op == "neg":
                        break
                    reduce_operator()
                operators.append(op)
                expect_operand = True

        while operators:
            reduce_operator()
        return nodes[0]

    expressions = {}
    for name, content in cells.items():
        content = content.strip()
        expressions[name] = (
            parse(content[1:])
            if content.startswith("=")
            else ("number", int(content))
        )

    values = {}
    active = set()

    # Each generator yields the next expression it needs evaluated.
    # An explicit stack drives the generators without recursive calls.
    def evaluate(node):
        kind = node[0]

        if kind == "number":
            return node[1]

        if kind == "ref":
            name = node[1]
            if name not in expressions:
                return 0
            if name in values:
                return values[name]
            if name in active:
                return "#CYCLE!"

            active.add(name)
            value = yield expressions[name]
            active.remove(name)
            values[name] = value
            return value

        if kind == "neg":
            value = yield node[1]
            return value if isinstance(value, str) else -value

        if kind == "IF":
            condition, then_branch, else_branch = node[1]
            result = yield condition
            if isinstance(result, str):
                return result
            return (yield then_branch if result else else_branch)

        if kind in ("SUM", "MIN", "MAX"):
            result = 0 if kind == "SUM" else None

            for argument in node[1]:
                if argument[0] == ":":
                    first = argument[1][1]
                    last = argument[2][1]
                    col_low, col_high = sorted((ord(first[0]), ord(last[0])))
                    row_low, row_high = sorted((int(first[1:]), int(last[1:])))

                    pending = (
                        ("ref", chr(col) + str(row))
                        for row in range(row_low, row_high + 1)
                        for col in range(col_low, col_high + 1)
                        if chr(col) + str(row) in expressions
                    )
                else:
                    pending = (argument,)

                for item in pending:
                    value = yield item
                    if isinstance(value, str):
                        return value

                    if kind == "SUM":
                        result += value
                    elif result is None:
                        result = value
                    elif kind == "MIN":
                        result = min(result, value)
                    else:
                        result = max(result, value)

            return 0 if result is None else result

        left = yield node[1]
        if isinstance(left, str):
            return left

        right = yield node[2]
        if isinstance(right, str):
            return right

        if kind == "+":
            return left + right
        if kind == "-":
            return left - right
        if kind == "*":
            return left * right
        if kind == "/":
            if right == 0:
                return "#DIV/0!"
            quotient = abs(left) // abs(right)
            return -quotient if (left < 0) != (right < 0) else quotient
        if kind == "=":
            return left == right
        if kind == "<>":
            return left != right
        if kind == "<":
            return left < right
        if kind == "<=":
            return left <= right
        if kind == ">":
            return left > right
        if kind == ">=":
            return left >= right

    for name in cells:
        if name in values:
            continue

        stack = [evaluate(("ref", name))]
        returned_value = None

        while stack:
            try:
                requested_node = stack[-1].send(returned_value)
            except StopIteration as completed:
                stack.pop()
                returned_value = completed.value
            else:
                stack.append(evaluate(requested_node))
                returned_value = None

    return {name: values[name] for name in cells}
